##### 层序遍历
参考：[二叉树的层序遍历【基础算法精讲 13】哔哩哔哩bilibili](https://www.bilibili.com/video/BV1hG4y1277i/?vd_source=876be08bc9c030f4a9ea1fb97e0d0342) 使用双数组更好理解：（这也是 [[#BFS|BFS]] 的逻辑） ![[Pasted image 20250222234358.png]]
-   `cur` 存储当前正在遍历的节点，用 cur 更新所有**下一步要遍历的节点**，存储在 next 中
-   直到 `cur.empty()` 表示没有节点需要处理了，终止循环


```cpp
class Solution {
public:
    vector<vector<int>> levelOrder(TreeNode* root) {
        if (root == NULL) return {};
        vector<TreeNode*> cur, next;
        vector<vector<int>> result;
        cur.push_back(root);
        while (!cur.empty()) {
            vector<int> level;
            for (auto node : cur) {
                level.push_back(node->val);
                if (node->left) next.push_back(node->left);
                if (node->right) next.push_back(node->right);
            }
            cur = next;
            next.clear();
            result.push_back(level);
        }
        return result;
    }
};
```


也可以只用一个队列完成 cur 和 next 的工作：
```cpp
class Solution {
public:
    vector<vector<int>> levelOrder(TreeNode* root) {
        queue<TreeNode*> que;
        if (root != NULL) que.push(root);
        vector<vector<int>> result;
        while (!que.empty()) {
            int size = que.size();
            vector<int> level;
            for (int i = 0;i < size;i++) {
                TreeNode* node = que.front();
                que.pop();
                level.push_back(node->val);
                if (node->left) que.push(node->left);
                if (node->right) que.push(node->right);
            }
            result.push_back(level);
        }
        return result;
    }
};
```
-   **必须**要使用固定 size，不要使用 `que.size()`，因 `que.size` 是不断变化，这样才可以每次 while 中 for 循环只跑完**当前行**的节点


使用 DFS，**注意是 DFS**
```cpp
class Solution {
public:
    int treeDepth(TreeNode* root) {
        if (root == NULL) return 0;
        int max_left = treeDepth(root->left);
        int max_right = treeDepth(root->right);
        return max(max_left, max_right) + 1;
    }
    void dfs(vector<vector<int>>& result, TreeNode* node, int deep) {
        if (node == NULL) return;
        else {
            result[deep].push_back((node->val));
            // 不使用treeDepth函数临时在result后添加数组也可以
            // if(result.size() == deep) result.push_back(vector<int>());
            // 第一次访问新行，创建在相应位置创建数组，而不是每个循环都添加值
            dfs(result, node->left, deep + 1);
            dfs(result, node->right, deep + 1);
        }
    }
    vector<vector<int>> levelOrder(TreeNode* root) {
        int deep = treeDepth(root);
        vector<vector<int>> result(deep);
        dfs(result, root, 0);
        return result;
    }
};
```

